 "workflow": "name: API tests (Postman)\non:\n  pull_request:\n  push:\n    branches: [main]\n\njobs:\n  newman:\n    runs-on: ubuntu-24.04\n    timeout-minutes: 10\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci --omit=dev\n      - name: Start the API in the background\n        run: |\n          ALLOW_RESET=1 PORT=4173 node postman/server.js > api.log 2>&1 &\n          for i in $(seq 30); do curl -sf http://localhost:4173/api/health && exit 0; sleep 1; done\n          echo \"API did not start\"; cat api.log; exit 1\n      - name: Run the collection\n        run: >\n          npx --yes newman@6.2.3 run postman/labflow.postman_collection.json\n          -e postman/ci.postman_environment.json\n          --env-var \"password=${{ secrets.LABFLOW_DEMO_PASSWORD }}\"\n          --reporters cli,junit\n          --reporter-junit-export reports/newman.xml\n      - name: Keep the report, green or red\n        if: always()\n        uses: actions/upload-artifact@v4\n        with:\n          name: newman-report\n          path: |\n            reports/newman.xml\n            api.log",
