 "mockSpec": "{\n  \"requestBody\": {\n    \"required\": true,\n    \"content\": {\n      \"application/json\": {\n        \"schema\": {\n          \"type\": \"object\",\n          \"additionalProperties\": false,\n          \"required\": [\n            \"lab\",\n            \"date\",\n            \"start\",\n            \"end\",\n            \"seats\"\n          ],\n          \"properties\": {\n            \"lab\": {\n              \"type\": \"string\",\n              \"pattern\": \"^[A-Z]{2}-[0-9]{3}$\"\n            },\n            \"date\": {\n              \"type\": \"string\",\n              \"format\": \"date\"\n            },\n            \"start\": {\n              \"type\": \"string\",\n              \"pattern\": \"^([01][0-9]|2[0-3]):[0-5][0-9]$\"\n            },\n            \"end\": {\n              \"type\": \"string\",\n              \"pattern\": \"^([01][0-9]|2[0-3]):[0-5][0-9]$\"\n            },\n            \"seats\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 200\n            }\n          }\n        }\n      }\n    }\n  },\n  \"responses\": {\n    \"201\": {\n      \"description\": \"Created\",\n      \"content\": {\n        \"application/json\": {\n          \"schema\": {\n            \"$ref\": \"#/components/schemas/Booking\"\n          },\n          \"example\": {\n            \"id\": 1,\n            \"lab\": \"BE-201\",\n            \"date\": \"2026-12-01\",\n            \"start\": \"09:00\",\n            \"end\": \"11:00\",\n            \"seats\": 20,\n            \"status\": \"CONFIRMED\",\n            \"minutes\": 120\n          }\n        }\n      },\n      \"headers\": {\n        \"Location\": {\n          \"schema\": {\n            \"type\": \"string\"\n          },\n          \"example\": \"/api/bookings/1\"\n        }\n      }\n    },\n    \"409\": {\n      \"description\": \"Slot taken\",\n      \"content\": {\n        \"application/json\": {\n          \"schema\": {\n            \"$ref\": \"#/components/schemas/Error\"\n          },\n          \"example\": {\n            \"error\": {\n              \"code\": \"OVERLAP\"\n            }\n          }\n        }\n      }\n    }\n  }\n}",
 "bru1": "meta {\n  name: Login as an\n  type: http\n  seq: 1\n}\n\npost {\n  url: {{baseUrl}}/api/login\n  body: json\n  auth: none\n}\n\nbody:json {\n  { \"username\": \"an\", \"password\": \"labflow-demo\" }\n}\n\nscript:post-response {\n  bru.setVar(\"token\", res.body.token);\n}\n\ntests {\n  test(\"200 and a token\", function () {\n    expect(res.status).to.equal(200);\n    expect(res.body.token).to.be.a(\"string\");\n  });\n}",
 "bru2": "meta {\n  name: Create booking\n  type: http\n  seq: 2\n}\n\npost {\n  url: {{baseUrl}}/api/bookings\n  body: json\n  auth: bearer\n}\n\nauth:bearer {\n  token: {{token}}\n}\n\nbody:json {\n  { \"lab\": \"BE-301\", \"date\": \"2026-12-02\", \"start\": \"09:00\", \"end\": \"10:00\", \"seats\": 12 }\n}\n\nscript:post-response {\n  bru.setVar(\"bookingId\", res.body.id);\n}\n\ntests {\n  test(\"201 + Location\", function () {\n    expect(res.status).to.equal(201);\n    expect(res.headers.location).to.equal(\"/api/bookings/\" + res.body.id);\n  });\n}",
